public class InvocationMatcher_captureArgumentsFrom_TriageGen0Test {

    // Mock implementation of CapturesArguments to verify behavior
    public interface CapturesArguments extends Matcher {
        void captureFrom(Object argument);
    }

    @Test
    public void testCaptureArgumentsFrom_WithVarArgs_ThrowsUnsupportedOperationException() throws NoSuchMethodException {
        // Setup: A method that is varargs
        Method varargsMethod = String[].class.getMethod("toString", Object[].class); 
        // Note: In real Mockito, we'd use a real method. Let's simulate a varargs method.
        Method realVarargsMethod = MyTestClass.varargsMethod;

        Invocation invocation = mock(Invocation.class);
        when(invocation.getMethod()).thenReturn(realVarargsMethod);
        when(invocation.getRawArguments()).thenReturn(new Object[]{new Object[]{1, 2}});

        // The class under test requires matchers list in constructor
        List<Matcher> matchers = new ArrayList<>();
        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);

        try {
            matcher.captureArgumentsFrom(invocation);
        } catch (UnsupportedOperationException e) {
            // Success
        } else {
            throw new AssertionError("Expected UnsupportedOperationException");
        }
    }

    @Test
    public void testCaptureArgumentsFrom_NonVarArgs_CapturesCorrectArguments() throws NoSuchMethodException {
        // Setup: A non-varargs method
        Method nonVarargsMethod = String.class.getMethod("length");

        Invocation invocation = mock(Invocation.class);
        when(invocation.getMethod()).thenReturn(nonVarargsMethod);
        when(invocation.getRawArguments()).thenReturn(new Object[]{"hello", "world"});

        // Mocking getArgumentAt(position, Class)
        when(invocation.getArgumentAt(0, Object.class)).thenReturn("hello");
        when(invocation.getArgumentAt(1, Object.class)).thenReturn("world");

        CapturesArguments capturer1 = mock(CapturesArguments.class);
        CapturesArguments capturer2 = mock(CapturesArguments.class);
        Matcher normalMatcher = mock(Matcher.class);

        List<Matcher> matchers = Arrays.asList(capturer1, normalMatcher, capturer2);
        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);

        matcher.captureArgumentsFrom(invocation);

        // Verify capturers were called with correct arguments
        verify(capturer1).captureFrom("hello");
        verify(capturer2).captureFrom("world");
        // normalMatcher should not be called because it's not an instance of CapturesArguments
    }

    @Test
    public void testCaptureArgumentsFrom_NonVarArgs_NoMatchers() throws NoSuchMethodException {
        Method nonVarargsMethod = String.class.getMethod("length");
        Invocation invocation = mock(Invocation.class);
        when(invocation.getMethod()).thenReturn(nonVarargsMethod);

        List<Matcher> matchers = new ArrayList<>();
        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);

        // Should not throw exception and just return
        matcher.captureArgumentsFrom(invocation);
    }

    @Test
    public void testCaptureArgumentsFrom_NonVarArgs_EmptyArguments() throws NoSuchMethodException {
        Method nonVarargsMethod = String.class.getMethod("length");
        Invocation invocation = mock(Invocation.class);
        when(invocation.getMethod()).thenReturn(nonVarargsMethod);
        when(invocation.getRawArguments()).thenReturn(new Object[]{});

        CapturesArguments capturer = mock(CapturesArguments.class);
        List<Matcher> matchers = Arrays.asList(capturer);
        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);

        // Since matchers.size() is 1 but invocation has 0 args, 
        // logic depends on how getArgumentAt handles out of bounds.
        // Based on code: it calls invocation.getArgumentAt(0, Object.class)
        // If that throws, the test confirms current behavior.
        try {
            matcher.captureArgumentsFrom(invocation);
        } catch (IndexOutOfBoundsException | IllegalArgumentException e) {
            // Expected if getArgumentAt is strict
        }
    }

    // Helper class to provide a varargs method for testing
    public static class MyTestClass {
        public void varargsMethod(String... args) {}
    }
}
